R=[
Rw('Spin quantum number (ms)','اسپن کوانٹم عدد (ms)','د اسپین کوانټم شمېره (ms)','The quantum number that specifies the direction in which the electron is spinning with values of +1/2 and -1/2','وہ کوانٹم عدد جو اس سمت کا تعین کرتا ہے جس میں الیکٹران گھوم رہا ہے، قیمتیں +1/2 اور -1/2','هغه کوانټم شمېره چې هغه لوری ټاکي چې الکترون په هغه کې څرخېږي، ارزښتونه +1/2 او -1/2'),
Rw('Standard electrode potential','معیاری الیکٹروڈ پوٹینشل','معیاري الکترود پوټنشیل','The potential developed by a metal or other material immersed in an electrolyte solution relative to the potential of the hydrogen electrode, which is set at zero','وہ پوٹینشل جو برق پاش محلول میں ڈوبی ہوئی دھات یا دوسرے مادے سے پیدا ہوتا ہے، ہائیڈروجن الیکٹروڈ کے پوٹینشل کے حوالے سے جو صفر مقرر کیا گیا ہے','هغه پوټنشیل چې په الکترولایټ محلول کې ډوب شوي فلز یا بلې مادې په واسطه رامنځته کېږي، د هایدروجن الکترود د پوټنشیل په اړه چې صفر ټاکل شوی'),
Rw('Standard enthalpy of neutralization (ΔH°n)','معیاری اینتھیلپی تعدیل (ΔH°n)','د خنثی کېدو معیاري انتالپي (ΔH°n)','It is the enthalpy change when one mole of an acid is neutralized by one mole of a base.','یہ اینتھیلپی کی تبدیلی ہے جب ایک مول تیزاب ایک مول اساس سے معتدل ہو۔','دا د انتالپي بدلون دی کله چې یو مول اسید د یو مول اساس په واسطه خنثی شي.'),
Rw('Standard Enthalpy of solution (ΔH°s)','معیاری اینتھیلپی حل (ΔH°s)','د محلول معیاري انتالپي (ΔH°s)','It is the change in enthalpy when one mole of a substance is dissolved in a solvent so that further dissolution does not give any change in enthalpy.','یہ اینتھیلپی کی تبدیلی ہے جب ایک مول مادہ کسی محلل میں اس طرح حل ہو کہ مزید حل ہونے سے اینتھیلپی میں کوئی تبدیلی نہ آئے۔','دا د انتالپي بدلون دی کله چې د یوې مادې یو مول په یو محلل کې داسې منحل شي چې نور منحلېدل د انتالپي کې هېڅ بدلون نه راولي.'),
Rw('Standard solution','معیاری محلول','معیاري محلول','A solution of known concentration','معلوم ارتکاز کا محلول','د معلوم غلظت محلول'),
Rw('Standard temperature and pressure, STP','معیاری درجہ حرارت اور دباؤ، STP','معیاري تودوخه او فشار، STP','The standard temperature is 0°C(273K) and the standard pressure is 1 atm or 760mm of Hg or 760 torr or 101325Nm⁻².','معیاری درجہ حرارت 0°C (273K) ہے اور معیاری دباؤ 1 atm یا 760mm Hg یا 760 torr یا 101325Nm⁻² ہے۔','معیاري تودوخه 0°C (273K) ده او معیاري فشار 1 atm یا 760mm Hg یا 760 torr یا 101325Nm⁻² دی.'),
Rw('State','حالت','حالت','A complete description of the system is called its state. It is a particular set of conditions of pressure, temperature, volume and volume amount of each component of a system.','نظام کی مکمل تفصیل اس کی حالت کہلاتی ہے۔ یہ نظام کے ہر جز کے دباؤ، درجہ حرارت، حجم اور حجمی مقدار کی شرائط کا ایک خاص سیٹ ہے۔','د سیستم بشپړ تشریح د هغه حالت بلل کېږي. دا د یوې سیستم د هرې برخې د فشار، تودوخې، حجم او حجمي مقدار د شرایطو یو ځانګړی سیټ دی.'),
Rw('State function','حالت تفاعل','د حالت فنکشن','The properties of a system which uniquely define the state of a system are called state functions. A state function depends on initial and final states of a system and is independent of the path fowled.','نظام کی وہ خصوصیات جو نظام کی حالت کو منفرد طور پر متعین کرتی ہیں حالتی تفاعل کہلاتی ہیں۔ حالتی تفاعل نظام کی ابتدائی اور آخری حالتوں پر منحصر ہوتا ہے اور اختیار کردہ راستے سے آزاد ہوتا ہے۔','د سیستم هغه ځانګړتیاوې چې د سیستم حالت په ځانګړي ډول ټاکي د حالت فنکشنونه بلل کېږي. د حالت فنکشن د سیستم په لومړني او وروستي حالتونو پورې اړه لري او له تعقیب شوې لارې څخه خپلواک وي.'),
Rw('Stoichiometry','سٹوئیکیومیٹری (کیمیائی حسابیات)','سټوکیومیټري','The area of chemistry that deals with the quantitative relationships among reactants and products in a chemical reaction','کیمیا کا وہ شعبہ جو کیمیائی تعامل میں متعاملات اور حاصلات کے درمیان مقداری تعلقات سے متعلق ہے','د کیمیا هغه ساحه چې په کیمیاوي تعامل کې د تعامل کوونکو او محصولاتو ترمنځ له کمیتي اړیکو سره معامله کوي'),
Rw('Strong electrolytes','مضبوط برق پاش','قوي الکترولایټونه','An electrolyte that is 100% ionized in solution or in molten state is called a strong electrolyte e.g. NaCl, NaOH and HCl','وہ برق پاش جو محلول میں یا پگھلی حالت میں 100% آئنائز ہو مضبوط برق پاش کہلاتا ہے مثلاً NaCl، NaOH اور HCl','هغه الکترولایټ چې په محلول یا ویلې شوې حالت کې 100% آیونایز وي قوي الکترولایټ بلل کېږي لکه NaCl، NaOH او HCl'),
Rw('Substance','مادہ (خالص)','ماده','Matter that is homogeneous and has a definite, fixed composition; substances occur in two forms—as elements and as compounds.','وہ مادہ جو یکساں ہو اور اس کی متعین، مقررہ ترکیب ہو؛ خالص مادے دو صورتوں میں پائے جاتے ہیں—عناصر کے طور پر اور مرکبات کے طور پر۔','هغه ماده چې همجنسه وي او ټاکلی، ثابت جوړښت ولري؛ مواد په دوو بڼو کې شتون لري—د عناصرو په توګه او د مرکباتو په توګه.'),
Rw('Substrate','تہہ (سبسٹریٹ)','سبسټریټ','In biochemical reactions, the substrate is the unit acted upon by an enzyme.','حیاتی کیمیائی تعاملات میں سبسٹریٹ وہ اکائی ہے جس پر خامرہ عمل کرتا ہے۔','په بایوکیمیاوي تعاملاتو کې سبسټریټ هغه واحد دی چې انزایم پرې عمل کوي.'),
Rw('Surface tension','سطحی تناؤ','سطحي کشش','The resistance of a liquid to an increase in its surface area.','مائع کے سطحی رقبے میں اضافے کے خلاف مزاحمت۔','د مایع د سطحي ساحې په زیاتوالي پر وړاندې مقاومت.'),
Rw('System (thermodynamic)','نظام (حرکیاتِ حرارت)','سیستم (ترموډینامیک)','That part of the universe on which attention is to be focused.','کائنات کا وہ حصہ جس پر توجہ مرکوز کی جانی ہو۔','د کائناتو هغه برخه چې پام پرې ټینګېږي.')]
